-- Ensure embeddings column matches target dimension (1024)
DO $$
DECLARE
    v_current_dim INTEGER;
BEGIN
    -- Check current vector dimension on the embeddings table
    SELECT atttypmod INTO v_current_dim
    FROM pg_attribute
    WHERE attrelid = 'public.embeddings'::regclass
      AND attname = 'embedding';

    IF v_current_dim IS NOT NULL AND v_current_dim != 1024 THEN
        RAISE NOTICE '⚠️  DIMENSION TRIM: embeddings.embedding column resized from % to 1024 dimensions. Source vectors will be truncated to fit.', v_current_dim;
